import sys,numpy as np
from scipy.optimize import least_squares
sys.path.insert(0,'/app/output');import gen
spec=gen.spec; P=np.array(spec['arm']['position_m']+[spec['arm']['end_effector']['position_m']]); ax=np.array(spec['arm']['axis'])
now=np.array(gen.r.get_obs(cameras=['robot_wrist'],include_depth=True,video='none').meta['proprio']['now'],float);q0=now[6:13]
def rot(a,t):
 a=a/np.linalg.norm(a);K=np.array([[0,-a[2],a[1]],[a[2],0,-a[0]],[-a[1],a[0],0]])
 return np.eye(3)*np.cos(t)+np.outer(a,a)*(1-np.cos(t))+K*np.sin(t)
def fk(q):
 R=np.eye(3); p=P[0]
 for i in range(7):
  if i: p=p+R@(P[i]-P[i-1])
  R=R@rot(ax[i],q[i])
 return p+R@(P[7]-P[6]), R, p+R@np.array([0,.0564,.0584])
# wrist image pixel at center of thin handle
u,v=36,145; dep=.56; fx=240/np.tan(np.deg2rad(41.8/2));
ee,R,pc=fk(q0); F=R@np.array([0,0,1]); right=R@np.array([-1,0,0]); up=R@np.array([0,1,0]);
tgt=pc+dep*F+dep*(u-320)/fx*right+dep*(240-v)/fx*up
print('q0',q0);print('camera',pc,'F',F,'target',tgt,'ee',ee)
def residual(q):
 p,Rc,_=fk(q); z=Rc[:,2]
 return np.r_[ (p-tgt)*8, (z-np.array([0,0,-1]))*0.5]
lb=np.array([-np.inf,-2.24,-np.inf,-2.57,-np.inf,-2.09,-np.inf]);ub=-lb
sol=least_squares(residual,q0,bounds=(lb,ub),max_nfev=1000)
print('sol',sol.x,'res',residual(sol.x),'pos',fk(sol.x)[0],'z',fk(sol.x)[1][:,2])
